local Math = {}
function Math.lerp(a, b, t) return a + (b - a) * math.clamp(t, 0, 1) end
function Math.smoothstep(t) t = math.clamp(t, 0, 1) return t * t * (3 - 2 * t) end
function Math.smootherstep(t) t = math.clamp(t, 0, 1) return t * t * t * (t * (t * 6 - 15) + 10) end
function Math.distance(x1, y1, x2, y2) return math.sqrt((x2 - x1)^2 + (y2 - y1)^2) end
function Math.clamp(v, min, max) return math.max(math.min(v, max), min) end
function Math.map(v, inMin, inMax, outMin, outMax) return (v - inMin) / (inMax - inMin) * (outMax - outMin) + outMin end
function Math.sin(a) return math.sin(math.rad(a)) end
function Math.cos(a) return math.cos(math.rad(a)) end
function Math.tan(a) return math.tan(math.rad(a)) end
function Math.asin(a) return math.deg(math.asin(a)) end
function Math.acos(a) return math.deg(math.acos(a)) end
function Math.atan(a) return math.deg(math.atan(a)) end
function Math.atan2(y, x) return math.deg(math.atan2(y, x)) end
function Math.sinh(x) return (math.exp(x) - math.exp(-x)) / 2 end
function Math.cosh(x) return (math.exp(x) + math.exp(-x)) / 2 end
function Math.tanh(x) return Math.sinh(x) / Math.cosh(x) end
function Math.log10(x) return math.log(x, 10) end
function Math.log2(x) return math.log(x, 2) end
function Math.gcd(a, b) while b > 0 do a, b = b, a % b end return a end
function Math.lcm(a, b) return a * b / Math.gcd(a, b) end
function Math.isPrime(n) if n < 2 then return false end if n == 2 then return true end if n % 2 == 0 then return false end for i = 3, math.sqrt(n), 2 do if n % i == 0 then return false end end return true end
function Math.factorial(n) if n <= 1 then return 1 end return n * Math.factorial(n - 1) end
function Math.combinations(n, k) return Math.factorial(n) / (Math.factorial(k) * Math.factorial(n - k)) end
function Math.permutations(n, k) return Math.factorial(n) / Math.factorial(n - k) end
function Math.degree(rad) return rad * 180 / math.pi end
function Math.radian(deg) return deg * math.pi / 180 end
function Math.hypot(x, y, z) if not z then return math.sqrt(x * x + y * y) end return math.sqrt(x * x + y * y + z * z) end
function Math.pow(base, exp) return base ^ exp end
function Math.sqrt(x) return math.sqrt(x) end
function Math.cbrt(x) return x ^ (1/3) end
function Math.abs(x) return math.abs(x) end
function Math.sign(x) return x > 0 and 1 or (x < 0 and -1 or 0) end
function Math.floor(x) return math.floor(x) end
function Math.ceil(x) return math.ceil(x) end
function Math.round(x) return math.floor(x + 0.5) end
function Math.truncate(x) return math.floor(x) end
function Math.fmod(x, y) return x - math.floor(x / y) * y end
function Math.fract(x) return x - math.floor(x) end

local String = {}
function String.split(str, delim) local result = {} for match in (str .. delim):gmatch("(.-)" .. delim) do table.insert(result, match) end return result end
function String.trim(str) return str:match("^%s*(.-)%s*$") end
function String.ltrim(str) return str:match("^%s*(.*)$") end
function String.rtrim(str) return str:match("^(.-)%s*$") end
function String.startsWith(str, prefix) return str:sub(1, #prefix) == prefix end
function String.endsWith(str, suffix) return str:sub(-#suffix) == suffix end
function String.reverse(str) return str:reverse() end
function String.upper(str) return str:upper() end
function String.lower(str) return str:lower() end
function String.capitalize(str) return str:sub(1, 1):upper() .. str:sub(2):lower() end
function String.repeat(str, count) return string.rep(str, count) end
function String.contains(str, sub) return str:find(sub, 1, true) ~= nil end
function String.replace(str, old, new) return str:gsub(old, new) end
function String.indexOf(str, sub) local pos = str:find(sub, 1, true) return pos and pos - 1 or -1 end
function String.lastIndexOf(str, sub) local pos = str:reverse():find(sub:reverse(), 1, true) return pos and #str - pos - #sub + 2 or -1 end
function String.padStart(str, len, char) char = char or " " return string.rep(char, math.max(0, len - #str)) .. str end
function String.padEnd(str, len, char) char = char or " " return str .. string.rep(char, math.max(0, len - #str)) end
function String.slice(str, start, finish) return str:sub(start + 1, finish) end
function String.substring(str, start, finish) local a, b = math.min(start, finish), math.max(start, finish) return str:sub(a + 1, b) end
function String.concat(...) return table.concat({...}) end
function String.toCharArray(str) local arr = {} for i = 1, #str do arr[i] = str:sub(i, i) end return arr end
function String.fromCharCode(...) return string.char(...) end

local Table = {}
function Table.insert(tbl, val) table.insert(tbl, val) return tbl end
function Table.remove(tbl, index) return table.remove(tbl, index) end
function Table.concat(tbl, sep) return table.concat(tbl, sep or "") end
function Table.copy(tbl) local result = {} for k, v in pairs(tbl) do result[k] = v end return result end
function Table.deepCopy(tbl) local result = {} for k, v in pairs(tbl) do if type(v) == "table" then result[k] = Table.deepCopy(v) else result[k] = v end end return result end
function Table.merge(t1, t2) local result = Table.copy(t1) for k, v in pairs(t2) do result[k] = v end return result end
function Table.reverse(tbl) local result = {} for i = #tbl, 1, -1 do table.insert(result, tbl[i]) end return result end
function Table.contains(tbl, val) for _, v in ipairs(tbl) do if v == val then return true end end return false end
function Table.indexOf(tbl, val) for i, v in ipairs(tbl) do if v == val then return i end end return -1 end
function Table.map(tbl, func) local result = {} for i, v in ipairs(tbl) do table.insert(result, func(v, i)) end return result end
function Table.filter(tbl, func) local result = {} for i, v in ipairs(tbl) do if func(v, i) then table.insert(result, v) end end return result end
function Table.reduce(tbl, func, init) local acc = init for i, v in ipairs(tbl) do acc = func(acc, v, i) end return acc end
function Table.find(tbl, func) for i, v in ipairs(tbl) do if func(v, i) then return v, i end end end
function Table.every(tbl, func) for _, v in ipairs(tbl) do if not func(v) then return false end end return true end
function Table.some(tbl, func) for _, v in ipairs(tbl) do if func(v) then return true end end return false end
function Table.clear(tbl) for k in pairs(tbl) do tbl[k] = nil end end
function Table.keys(tbl) local result = {} for k in pairs(tbl) do table.insert(result, k) end return result end
function Table.values(tbl) local result = {} for _, v in pairs(tbl) do table.insert(result, v) end return result end
function Table.count(tbl) local count = 0 for _ in pairs(tbl) do count = count + 1 end return count end
function Table.isEmpty(tbl) return Table.count(tbl) == 0 end
function Table.flatten(tbl) local result = {} local function flat_rec(t) for _, v in ipairs(t) do if type(v) == "table" then flat_rec(v) else table.insert(result, v) end end end flat_rec(tbl) return result end
function Table.unique(tbl) local result = {} local seen = {} for _, v in ipairs(tbl) do if not seen[v] then seen[v] = true table.insert(result, v) end end return result end
function Table.shuffle(tbl) local result = Table.copy(tbl) for i = #result, 2, -1 do local j = math.random(1, i) result[i], result[j] = result[j], result[i] end return result end
function Table.sort(tbl, comp) local result = Table.copy(tbl) table.sort(result, comp) return result end
function Table.sortBy(tbl, key) return Table.sort(tbl, function(a, b) return a[key] < b[key] end) end
function Table.min(tbl) local min = tbl[1] for i = 2, #tbl do if tbl[i] < min then min = tbl[i] end end return min end
function Table.max(tbl) local max = tbl[1] for i = 2, #tbl do if tbl[i] > max then max = tbl[i] end end return max end
function Table.sum(tbl) local sum = 0 for _, v in ipairs(tbl) do sum = sum + v end return sum end
function Table.average(tbl) return #tbl > 0 and Table.sum(tbl) / #tbl or 0 end
function Table.range(start, stop, step) step = step or 1 local result = {} if start <= stop then for i = start, stop, step do table.insert(result, i) end else for i = start, stop, -step do table.insert(result, i) end end return result end

local Algorithms = {}
function Algorithms.binarySearch(tbl, target) local left, right = 1, #tbl while left <= right do local mid = math.floor((left + right) / 2) if tbl[mid] == target then return mid elseif tbl[mid] < target then left = mid + 1 else right = mid - 1 end end return -1 end
function Algorithms.linearSearch(tbl, target) for i, v in ipairs(tbl) do if v == target then return i end end return -1 end
function Algorithms.bubbleSort(tbl) local result = Table.copy(tbl) local n = #result for i = 1, n do for j = 1, n - i do if result[j] > result[j + 1] then result[j], result[j + 1] = result[j + 1], result[j] end end end return result end
function Algorithms.insertionSort(tbl) local result = Table.copy(tbl) for i = 2, #result do local key = result[i] local j = i - 1 while j > 0 and result[j] > key do result[j + 1] = result[j] j = j - 1 end result[j + 1] = key end return result end
function Algorithms.selectionSort(tbl) local result = Table.copy(tbl) local n = #result for i = 1, n - 1 do local minIdx = i for j = i + 1, n do if result[j] < result[minIdx] then minIdx = j end end result[i], result[minIdx] = result[minIdx], result[i] end return result end
function Algorithms.quickSort(tbl) if #tbl <= 1 then return Table.copy(tbl) end local pivot = tbl[1] local left, right = {}, {} for i = 2, #tbl do if tbl[i] < pivot then table.insert(left, tbl[i]) else table.insert(right, tbl[i]) end end local result = Algorithms.quickSort(left) table.insert(result, pivot) for _, v in ipairs(Algorithms.quickSort(right)) do table.insert(result, v) end return result end
function Algorithms.mergeSort(tbl) if #tbl <= 1 then return Table.copy(tbl) end local mid = math.floor(#tbl / 2) local left = Algorithms.mergeSort({unpack(tbl, 1, mid)}) local right = Algorithms.mergeSort({unpack(tbl, mid + 1)}) local result = {} local i, j = 1, 1 while i <= #left and j <= #right do if left[i] <= right[j] then table.insert(result, left[i]) i = i + 1 else table.insert(result, right[j]) j = j + 1 end end while i <= #left do table.insert(result, left[i]) i = i + 1 end while j <= #right do table.insert(result, right[j]) j = j + 1 end return result end
function Algorithms.fibonacci(n) if n <= 1 then return n end return Algorithms.fibonacci(n - 1) + Algorithms.fibonacci(n - 2) end
function Algorithms.gcd(a, b) while b > 0 do a, b = b, a % b end return a end
function Algorithms.lcm(a, b) return a * b / Algorithms.gcd(a, b) end

local Color = {}
function Color.fromRGB(r, g, b) return Color3.fromRGB(r, g, b) end
function Color.fromHex(hex) hex = hex:gsub("#", "") return Color3.fromRGB(tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16)) end
function Color.toHex(color) return string.format("#%02X%02X%02X", math.floor(color.R * 255), math.floor(color.G * 255), math.floor(color.B * 255)) end
function Color.lerp(c1, c2, t) t = Math.clamp(t, 0, 1) return Color3.new(Math.lerp(c1.R, c2.R, t), Math.lerp(c1.G, c2.G, t), Math.lerp(c1.B, c2.B, t)) end
function Color.invert(c) return Color3.new(1 - c.R, 1 - c.G, 1 - c.B) end
function Color.brightness(c) return (c.R + c.G + c.B) / 3 end

local Vector = {}
function Vector.magnitude(v) return math.sqrt(v.X * v.X + v.Y * v.Y + v.Z * v.Z) end
function Vector.normalize(v) local mag = Vector.magnitude(v) if mag == 0 then return v end return v / mag end
function Vector.dot(v1, v2) return v1.X * v2.X + v1.Y * v2.Y + v1.Z * v2.Z end
function Vector.cross(v1, v2) return Vector3.new(v1.Y * v2.Z - v1.Z * v2.Y, v1.Z * v2.X - v1.X * v2.Z, v1.X * v2.Y - v1.Y * v2.X) end
function Vector.distance(v1, v2) return (v1 - v2).Magnitude end
function Vector.lerp(v1, v2, t) return v1 + (v2 - v1) * Math.clamp(t, 0, 1) end

local AnimationCurve = {}
function AnimationCurve.linear(t) return t end
function AnimationCurve.easeInQuad(t) return t * t end
function AnimationCurve.easeOutQuad(t) return 1 - (1 - t) * (1 - t) end
function AnimationCurve.easeInOutQuad(t) return t < 0.5 and 2 * t * t or 1 - 2 * (1 - t) * (1 - t) end
function AnimationCurve.easeInCubic(t) return t * t * t end
function AnimationCurve.easeOutCubic(t) return 1 - (1 - t) * (1 - t) * (1 - t) end
function AnimationCurve.easeInOutCubic(t) return t < 0.5 and 4 * t * t * t or 1 - 4 * (1 - t) * (1 - t) * (1 - t) end
function AnimationCurve.easeInQuart(t) return t * t * t * t end
function AnimationCurve.easeOutQuart(t) return 1 - (1 - t)^4 end
function AnimationCurve.easeInQuint(t) return t^5 end
function AnimationCurve.easeOutQuint(t) return 1 - (1 - t)^5 end
function AnimationCurve.easeInSine(t) return 1 - math.cos((t * math.pi) / 2) end
function AnimationCurve.easeOutSine(t) return math.sin((t * math.pi) / 2) end
function AnimationCurve.easeInExpo(t) return t == 0 and 0 or 2^(10 * t - 10) end
function AnimationCurve.easeOutExpo(t) return t == 1 and 1 or 1 - 2^(-10 * t) end
function AnimationCurve.easeInCirc(t) return 1 - math.sqrt(1 - t^2) end
function AnimationCurve.easeOutCirc(t) return math.sqrt(1 - (t - 1)^2) end
function AnimationCurve.elasticIn(t) return t == 0 and 0 or t == 1 and 1 or -2^(10 * (t - 1)) * math.sin((t - 1.075) * (2 * math.pi) / 0.3) end
function AnimationCurve.elasticOut(t) return t == 0 and 0 or t == 1 and 1 or 2^(-10 * t) * math.sin((t - 0.075) * (2 * math.pi) / 0.3) + 1 end
function AnimationCurve.bounceOut(t) if t < 1 / 2.75 then return 7.5625 * t * t elseif t < 2 / 2.75 then t = t - 1.5 / 2.75 return 7.5625 * t * t + 0.75 elseif t < 2.5 / 2.75 then t = t - 2.25 / 2.75 return 7.5625 * t * t + 0.9375 else t = t - 2.625 / 2.75 return 7.5625 * t * t + 0.984375 end end
function AnimationCurve.bounceIn(t) return 1 - AnimationCurve.bounceOut(1 - t) end
function AnimationCurve.backIn(t) return t * t * (2.70158 * t - 1.70158) end
function AnimationCurve.backOut(t) return 1 + (t - 1) * (t - 1) * (2.70158 * (t - 1) + 1.70158) end


