g_aurorahub.IntroSystem = {}
g_aurorahub.IntroSystem.isActive = false
g_aurorahub.IntroSystem.INTRO_DELAY = 5
g_aurorahub.IntroSystem.INTRO_DURATION = 10

function g_aurorahub.IntroSystem:CreateIntroGui()
    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "AuroraIntroGui"
    screenGui.ResetOnSpawn = false
    screenGui.DisplayOrder = 999
    
    local introFrame = Instance.new("Frame")
    introFrame.Size = UDim2.new(1, 0, 1, 0)
    introFrame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    introFrame.BackgroundTransparency = 0.2
    introFrame.BorderSizePixel = 0
    introFrame.Parent = screenGui
    
    local titleLabel = Instance.new("TextLabel")
    titleLabel.Size = UDim2.new(0.8, 0, 0.2, 0)
    titleLabel.Position = UDim2.new(0.1, 0, 0.25, 0)
    titleLabel.BackgroundTransparency = 1
    titleLabel.TextColor3 = Color3.fromRGB(100, 200, 255)
    titleLabel.TextScaled = true
    titleLabel.Font = Enum.Font.GothamBold
    titleLabel.Text = "AURORA HUB"
    titleLabel.Parent = introFrame
    
    local nameLabel = Instance.new("TextLabel")
    nameLabel.Size = UDim2.new(0.8, 0, 0.1, 0)
    nameLabel.Position = UDim2.new(0.1, 0, 0.45, 0)
    nameLabel.BackgroundTransparency = 1
    nameLabel.TextColor3 = Color3.fromRGB(150, 220, 255)
    nameLabel.TextScaled = true
    nameLabel.Font = Enum.Font.Gotham
    nameLabel.Text = "Aurora Hub Latest"
    nameLabel.Parent = introFrame
    
    local loadingLabel = Instance.new("TextLabel")
    loadingLabel.Size = UDim2.new(0.8, 0, 0.1, 0)
    loadingLabel.Position = UDim2.new(0.1, 0, 0.58, 0)
    loadingLabel.BackgroundTransparency = 1
    loadingLabel.TextColor3 = Color3.fromRGB(200, 200, 200)
    loadingLabel.TextScaled = true
    loadingLabel.Text = "Loading Aurora Hub..."
    loadingLabel.Parent = introFrame
    
    local loadingBar = Instance.new("Frame")
    loadingBar.Size = UDim2.new(0.4, 0, 0.03, 0)
    loadingBar.Position = UDim2.new(0.3, 0, 0.70, 0)
    loadingBar.BackgroundColor3 = Color3.fromRGB(50, 50, 50)
    loadingBar.BorderSizePixel = 0
    loadingBar.Parent = introFrame
    
    local loadingBarFill = Instance.new("Frame")
    loadingBarFill.Size = UDim2.new(0, 0, 1, 0)
    loadingBarFill.BackgroundColor3 = Color3.fromRGB(100, 200, 255)
    loadingBarFill.BorderSizePixel = 0
    loadingBarFill.Parent = loadingBar
    
    screenGui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
    return screenGui, loadingBarFill
end

function g_aurorahub.IntroSystem:ShowIntro()
    if self.isActive then return end
    self.screenGui, self.loadingBarFill = self:CreateIntroGui()
    self.isActive = true
    self.startTime = tick()
    local conn
    conn = RunService.Heartbeat:Connect(function()
        if self.isActive then
            local elapsed = tick() - self.startTime
            local progress = math.min(elapsed / self.INTRO_DURATION, 1)
            self.loadingBarFill.Size = UDim2.new(progress, 0, 1, 0)
            if elapsed >= self.INTRO_DURATION then
                self:HideIntro()
                conn:Disconnect()
            end
        end
    end)
end

function g_aurorahub.IntroSystem:HideIntro()
    if self.screenGui then self.screenGui:Destroy() end
    self.isActive = false
end

task.wait(g_aurorahub.IntroSystem.INTRO_DELAY)
g_aurorahub.IntroSystem:ShowIntro()


